-                    r.get::<String, _>("product_id") == p.id
-                        && r.get::<String, _>("language_id") == *id
-                }) && let Some(value) = row.get::<Option<String>, _>(field)
-                {
-                    // NULL falls back; an explicitly empty string is a translation.
